```java
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/
class BSTIterator{
    LinkedList<TreeNode> stack = new LinkedList<>();
    boolean reverse;
    BSTIterator(boolean reverse, TreeNode root){
        this.reverse=reverse;
        pushAll(root);
    }

    void pushAll(TreeNode root){
        if(root != null){
            stack.push(root);
            if(reverse){
                while(root.right != null){
                    stack.push(root.right);
                    root=root.right;
                }
            }else{
                while(root.left != null){
                    stack.push(root.left);
                    root=root.left;
                }
            }          
        }      
    }

    TreeNode next(){
        TreeNode temp = stack.pop();
        if(!reverse && temp.right != null) pushAll(temp.right);
        if(reverse && temp.left != null) pushAll(temp.left);
        return temp;
    }
}
class Solution {

    public boolean twoSumBST(TreeNode root, int k) {
        BSTIterator l = new BSTIterator(false, root);
        BSTIterator r = new BSTIterator(true, root);
        int k1 = l.next().data;
        int k2 = r.next().data;
        while(k1<k2){ 
            if((k1+k2) > k){
                k2 = r.next().data;
            }else if((k1+k2) < k){
                k1 = l.next().data;
            }else{
                return true;
            }
        }
        return false;
    }
}
```

